const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const laJollaPoint = ee.Geometry.Point([-117.2527, 32.8687]); // A point near La Jolla shores
  const analysisRegion = laJollaPoint.buffer(10000); // 10 km buffer around the point

  // Date ranges for analysis (7-day window centered on Aug 1)
  const date2018_start = '2018-07-29';
  const date2018_end = '2018-08-04';
  const date2017_start = '2017-07-29';
  const date2017_end = '2017-08-04';

  // 2. Data Acquisition & Check
  const sstCollection = ee.ImageCollection('NOAA/AVHRR/Pathfinder_V53/sst');

  // Function to process a single year's data
  const processYearData = (start, end, yearLabel) => {
    let collection = sstCollection
      .filterDate(start, end)
      .filterBounds(analysisRegion);

    // Check if collection is empty
    if (collection.size().getInfo() === 0) {
      console.log(`No images found for ${yearLabel} within the date range.`);
      return null;
    }

    // Apply quality mask: quality = 0 (highest quality) or 1 (next best)
    // The 'quality' band indicates the quality of the SST measurement.
    // 0 = highest quality, 1 = lower quality, 4 = cloudy, 5 = bad.
    collection = collection.map(image => {
      const qualityMask = image.select('quality').lte(1); // Select pixels with quality 0 or 1
      return image.updateMask(qualityMask);
    });

    // Take the median image over the period to reduce noise and fill gaps.
    const medianSST = collection.select('sst').median();

    // Check if the median image is null (e.g., all images masked out)
    if (!medianSST) {
      console.log(`Median image for ${yearLabel} is null after initial filtering.`);
      return null;
    }

    // Scale SST band (divide by 100) and mask out fill values (SST < 0 after scaling)
    const processedSST = medianSST.divide(100).rename('sst_celsius');
    const finalSST = processedSST.updateMask(processedSST.gt(0)); // Mask out values <= 0

    return finalSST;
  };

  // Process data for 2018
  const sst2018 = processYearData(date2018_start, date2018_end, '2018');
  if (sst2018 === null) {
    console.log("Empty collection or processing failure for 2018.");
    console.log("C1");
    return;
  }

  // Process data for 2017
  const sst2017 = processYearData(date2017_start, date2017_end, '2017');
  if (sst2017 === null) {
    console.log("Empty collection or processing failure for 2017.");
    console.log("C1");
    return;
  }

  // 3. Calculate mean SST and pixel counts for both years
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const reduction2018 = await sst2018.reduceRegion({
    reducer: reducer,
    geometry: analysisRegion,
    scale: 5000, // Use a larger scale for faster computation and stability
    maxPixels: 1e9,
    crs: 'EPSG:4326' // Specify CRS for consistency
  }).getInfo();

  const reduction2017 = await sst2017.reduceRegion({
    reducer: reducer,
    geometry: analysisRegion,
    scale: 5000,
    maxPixels: 1e9,
    crs: 'EPSG:4326'
  }).getInfo();

  const meanSST2018 = reduction2018 ? reduction2018['sst_celsius_mean'] : null;
  const pixels2018 = reduction2018 ? reduction2018['sst_celsius_count'] : 0;
  const meanSST2017 = reduction2017 ? reduction2017['sst_celsius_mean'] : null;
  const pixels2017 = reduction2017 ? reduction2017['sst_celsius_count'] : 0;

  // 4. Validation & Final Answer
  if (pixels2018 === 0 || pixels2017 === 0) {
    console.log(`2018 Pixels: ${pixels2018}, 2017 Pixels: ${pixels2017}`);
    console.log("No valid pixels after masking for one or both years.");
    console.log("C2");
    return;
  }

  if (meanSST2018 === null || isNaN(meanSST2018) || meanSST2017 === null || isNaN(meanSST2017)) {
    console.log(`2018 SST: ${meanSST2018}, 2017 SST: ${meanSST2017}`);
    console.log("Calculation resulted in None or NaN for one or both years.");
    console.log("C3");
    return;
  }

  console.log(`2018 Mean SST: ${meanSST2018.toFixed(2)} °C (Pixels: ${pixels2018})`);
  console.log(`2017 Mean SST: ${meanSST2017.toFixed(2)} °C (Pixels: ${pixels2017})`);

  if (meanSST2018 > meanSST2017) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
